class FeePayment { void pay(double n){System.out.println("Paid: "+n);} } class OnlinePayment extends FeePayment { void payFee(double n){System.out.println("Online: "+n*1.02);} } public class AccountPayments { static void process(FeePayment p,double n){if(p instanceof OnlinePayment)((OnlinePayment)p).payFee(n);else p.pay(n);} public static void main(String[] a){process(new OnlinePayment(),100);process(new FeePayment(),50);} }
